 public static void Verify(){foreach(var folder in new[]{Source,Export,Source+"Vegetation/"}){var m=JObject.Parse(File.ReadAllText(folder+"manifest.json"));foreach(var p in ((JObject)m["files"]).Properties())if(Path.GetFileName(p.Name)!=p.Name||Hash(File.ReadAllBytes(folder+p.Name))!=(string)p.Value)throw new IOException("Reference artifact hash");if(m["inputs"] is JObject refs)foreach(var p in refs.Properties())if(Hash(File.ReadAllBytes((string)p.Value["path"]))!=(string)p.Value["sha256"])throw new IOException("Reference input hash");}}
